```python
import random

# Define quote categories and quotes
quote_categories = {
    "inspirational": [
        "Every great dream begins with a dreamer. Always remember, you have within you the strength, the patience, and the passion to reach for the stars to change the world.",
        "Believe you can and you're halfway there.",
        "The only limit to our realization of tomorrow will be our doubts of today."
    ],
    "motivational": [
        "Success is not final, failure is not fatal: it is the courage to continue that counts.",
        "The only limit to our realization of tomorrow will be our doubts of today.",
        "The only real security that a man can have in this world is a reserve of knowledge, experience, and ability."
    ],
    "funny": [
        "I used to be indecisive. Now I'm not so sure.",
        "I'm not lazy, I'm just conserving my energy for more important things, like deciding what to wear tomorrow.",
        "I'm not a morning person. I'm a caffeine person."
    ]
}

def get_random_quote(category):
    if category in quote_categories:
        return random.choice(quote_categories[category])
    else:
        print(f"Sorry, '{category}' is not a valid quote category. Please choose from the available options.")
        return None

# Get user input and generate a random quote
while True:
    category = input("Enter a quote category (inspirational, motivational, or funny): ").lower()
    if category in quote_categories:
        random_quote = get_random_quote(category)
        if random_quote:
            print(f"Random quote: {random_quote}")
        else:
            print("No quotes found for this category.")
    else:
        print("Sorry, '{category}' is not a valid quote category. Please choose from the available options.")
```

This program will keep prompting the user for a quote category until a valid category is entered. Then, it will generate a random quote from the specified category and display it to the user.
